#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<vector<bool>> edge(n, vector<bool>(n, false));
    vector<pair<int, int>> edges;

    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        --a;
        --b;
        edge[a][b] = edge[b][a] = true;
        edges.emplace_back(a, b);
    }

    vector<vector<int>> complement(n);
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            if (!edge[i][j]) {
                complement[i].push_back(j);
                complement[j].push_back(i);
            }
        }
    }

    vector<int> color(n, 0);

    for (int start = 0; start < n; ++start) {
        if (color[start] != 0 || complement[start].empty()) continue;

        queue<int> q;
        color[start] = 1;
        q.push(start);

        while (!q.empty()) {
            int u = q.front();
            q.pop();

            for (int v : complement[u]) {
                if (color[v] == 0) {
                    color[v] = 3 - color[u];
                    q.push(v);
                } else if (color[v] == color[u]) {
                    cout << "NO\n";
                    return 0;
                }
            }
        }
    }

    string answer(n, 'b');
    for (int i = 0; i < n; ++i) {
        if (color[i] == 1) answer[i] = 'a';
        else if (color[i] == 2) answer[i] = 'c';
    }

    for (auto [u, v] : edges) {
        if (abs(answer[u] - answer[v]) > 1) {
            cout << "NO\n";
            return 0;
        }
    }

    cout << "YES\n" << answer << '\n';
    return 0;
}

